import styled from 'styled-components'
import { cores } from '../../styles' // Importando a variável de cores (assumindo que você tenha configurado isso)

export const Container = styled.section`
  display: flex;
  padding: 32px 0;
  background-color: ${cores.branco};
`

export const List = styled.ul<{ size: 'grande' | 'pequeno' }>`
  display: grid;
  grid-template-columns: 1fr 1fr;
  column-gap: 24px;
  margin-top: 40px;
  width: 100%;
`

export const Item = styled.li<{ size: 'grande' | 'pequeno' }>`
  width: ${(props) => (props.size === 'grande' ? '472px' : '338px')};
  height: ${(props) =>
    props.size === 'grande'
      ? '400px'
      : '338px'}; /* Altura alterada com base no tamanho */
  overflow: hidden; /* Garantindo que a imagem e o conteúdo não saiam do limite */

  img {
    width: 100%;
    height: 60%; /* Ajustando a imagem para que ela se ajuste ao tamanho */
    object-fit: cover;
  }

  h3 {
    font-size: 18px;
    font-weight: bold;
  }

  p {
    font-size: 14px;
    color: ${cores.rosa}; /* Supondo que você tenha definido essa cor no arquivo de estilos */
  }
`

export const Title = styled.h2`
  font-size: 18px;
  font-weight: bold;
  color: ${cores.preto};
`
